function cyclicArrayInvalidInputs(){
 const direct=inputArray('variant',[null]);direct.value.values[0]=direct;
 const unit=inputArray('variant',[null]);unit.value.values[0]={type:'empty',value:unit};
 const decimal=inputArray('variant',[null]);decimal.value.values[0]={type:'currency',value:decimal};
 const utf=inputArray('variant',[null]);utf.value.values[0]={type:'utf16',value:[utf]};
 const raw=[];raw.push(raw);
 const unknown={type:'unknown'};unknown.value=unknown;
 return [direct,unit,decimal,utf,raw,unknown];
}

const invalidArraySource = 'Public Function ArrayInputMustNotRun(ByVal value As Variant) As String\n ArrayInputMustNotRun = "executed"\nEnd Function\n';
async function verifyNativeArrayInputs(invoke){
  let calls=0,rejections=0;
  for(const group of nativeArrayInputFixture.groups){
    for(const testCase of group.cases){
      assert.deepEqual(runner.parseVbaArguments(JSON.stringify(testCase.args)),testCase.args,testCase.name+': JSON parser');
      const result=await invoke(group.source,testCase.procedure,testCase.args);
      assert.equal(result.error,undefined,testCase.name);
      assert.deepEqual(result.result,{type:'string',value:testCase.expected},testCase.name);
      calls++;
    }
  }
  for(const testCase of nativeArrayInputFixture.bigint_cases){
    const result=await invoke(nativeArrayInputFixture.bigint_source,'DescribeTypedArgument',[BigInt(testCase.value)]);
    assert.equal(result.error,undefined,'Raw BigInt '+testCase.value);
    assert.deepEqual(result.result,{type:'string',value:testCase.expected});
    calls++;
  }
  for(const testCase of nativeArrayInputFixture.bigint_array_cases){
    const descriptor=structuredClone(nativeArrayInputFixture.bigint_array_descriptor);
    descriptor.value.values=descriptor.value.values.map(value=>BigInt(value.value));
    const result=await invoke(nativeArrayInputFixture.bigint_array_source,'DescribeTypedArray',[descriptor,testCase.action]);
    assert.equal(result.error,undefined,'BigInt array action '+testCase.action);
    assert.deepEqual(result.result,{type:'string',value:testCase.expected});
    calls++;
  }
  for(const argument of [...arrayInvalidInputs,...bigintInvalidInputs,...cyclicArrayInvalidInputs()]){
    await assert.rejects(async()=>invoke(invalidArraySource,'ArrayInputMustNotRun',[argument]),error=>/invalid VBA argument/i.test(error.message));
    rejections++;
  }
  return {calls,rejections};
}
const arrayInputSession = new wasm.SpreadsheetVbaSession();
let directArrayCounts,workerArrayCounts;
try{
 directArrayCounts=await verifyNativeArrayInputs((source,procedure,args)=>
   arrayInputSession.run(emptyBook(),source,procedure,args,0,'ArrayInputs.xlsm',{errorLanguage:'ja-JP'}));
}finally{arrayInputSession.free();}
try{
 globalThis.Worker=BrowserWorker;
 runner.closeVbaProject();
 workerArrayCounts=await verifyNativeArrayInputs((source,procedure,args)=>
   runner.runVbaInWorker(emptyBook(),source,procedure,args,0,'ArrayInputs.xlsm',{applicationState:{},errorLanguage:'ja-JP'}));
}finally{runner.closeVbaProject();globalThis.Worker=priorWorker;}
assert.deepEqual(directArrayCounts,workerArrayCounts);
assert.equal(directArrayCounts.calls,149);
assert.equal(directArrayCounts.rejections,48);

