async function verifyNativeArrayEdges(invoke, compile) {
 let calls=0;
 for(const row of nativeArrayEdgeFixture.bounds.cases){
  assert.deepEqual(runner.parseVbaArguments(JSON.stringify([row.argument])),[row.argument],row.name);
  const result=await invoke(nativeArrayEdgeFixture.bounds.source,nativeArrayEdgeFixture.bounds.procedure,[row.argument]);
  assert.equal(result.error,undefined,row.name);assert.deepEqual(result.result,{type:'string',value:row.expected},row.name);calls++;
 }
 for(const row of nativeArrayEdgeFixture.worksheets.cases){
  const result=await invoke(nativeArrayEdgeFixture.worksheets.source,nativeArrayEdgeFixture.worksheets.procedure,[row.mode]);
  assert.equal(result.error,undefined,'worksheet mutation '+row.mode);assert.deepEqual(result.result,{type:'string',value:row.expected},'worksheet mutation '+row.mode);calls++;
 }
 for(const row of nativeArrayEdgeFixture.declarations){
  const compilation=await compile(row.source);calls++;
  if(row.outcome==='compile'){
   assert.equal(compilation.compiled,false,row.name);
   assert.equal(compilation.error.kind,'compile',row.name);
   assert.equal(compilation.error.message,'\u30b3\u30f3\u30d1\u30a4\u30eb \u30a8\u30e9\u30fc: '+row.expected,row.name);
  }else{
   assert.deepEqual(compilation,{compiled:true},row.name);
   const result=await invoke(row.source,row.procedure,[]);
   assert.equal(result.error,undefined,row.name);assert.deepEqual(result.result,{type:'string',value:row.expected},row.name);calls++;
  }
 }
 return calls;
}
const edgeSession=new wasm.SpreadsheetVbaSession();let directEdgeCalls,workerEdgeCalls;
try{
 directEdgeCalls=await verifyNativeArrayEdges((source,procedure,args)=>edgeSession.run(emptyBook(),source,procedure,args,0,'ArrayEdges.xlsm',{errorLanguage:'ja-JP'}),
 source=>edgeSession.compile(source,{errorLanguage:'ja-JP'}));
}finally{edgeSession.free();}
try{
 globalThis.Worker=BrowserWorker;runner.closeVbaProject();
 workerEdgeCalls=await verifyNativeArrayEdges((source,procedure,args)=>runner.runVbaInWorker(emptyBook(),source,procedure,args,0,'ArrayEdges.xlsm',{applicationState:{},errorLanguage:'ja-JP'}),
 async source=>{try{return await runner.compileVbaInWorker(source,{errorLanguage:'ja-JP'});}catch(error){if(error.compilation)return error.compilation;throw error;}});
}finally{runner.closeVbaProject();globalThis.Worker=priorWorker;}
