  const made=countedReferenceCall((...args)=>wasm[entry](...args))(emptyBook(),externalLeaseSource,array?'MakeLeaseArray':'MakeLease',[],0,'ReturnedOwner.xlsm',{});
  assert.equal(made.error,undefined);
